template:
{%- set kinds = [("component", "Components", "template"), ("stylesheet", "Stylesheets", none), ("css", "CSS", "css"), ("js", "JavaScript", "js")] -%}
{%- set found = value.get("items") or {} -%}
{%- set ancestors = value.get("ancestors") or {} -%}
<div class="studio-version" data-studio-version data-studio-branch="{{ value.branch }}" data-studio-number="{{ value.number }}">
<h1 class="studio-version-title" data-studio-version-title>Version {{ value.number }} of {{ value.branch }}</h1>
<p class="studio-hint">A version is read-only: the branch's own items as they were then. To restore it, use Restore in the history of the branch's workbench strip.</p>
<dl class="studio-version-record">
<div><dt>Based on</dt><dd>{% for name, number in ancestors|dictsort %}{{ name }} v{{ number }}{% if not loop.last %}, {% endif %}{% else %}nothing: a branch with no parent{% endfor %}</dd></div>
</dl>
{%- for kind, title, field in kinds %}
{%- set entries = found.get(kind) or [] %}
<section class="studio-version-kind" data-studio-version-kind="{{ kind }}" aria-label="{{ title }}">
<h2 class="studio-version-kind-title">{{ title }} ({{ entries|length }})</h2>
{%- if entries %}
<ul class="studio-version-items">
{%- for item in entries if item is mapping %}
<li class="studio-version-item{% if item.get("deleted") is sameas true %} studio-version-deleted{% endif %}" data-studio-version-item="{{ item.get("name") }}">
<span class="studio-version-name">{{ item.get("name") }}</span>
{%- if item.get("applies_to") %} <span class="studio-version-applies">applies to {{ item.get("applies_to") }}</span>{% endif %}
{%- if item.get("deleted") is sameas true %} <span class="studio-version-marker">deleted on this branch</span>
{%- elif field %}
<pre class="studio-version-code">{{ item.get(field) or "" }}</pre>
{%- else %}
<ul class="studio-version-rules">
{%- for rule in item.get("rules") or [] if rule is mapping %}<li>{{ rule.get("select") }} → {{ rule.get("component") }}</li>{% endfor -%}
</ul>
{%- endif %}
</li>
{%- endfor %}
</ul>
{%- else %}
<p class="studio-hint">None of its own.</p>
{%- endif %}
</section>
{%- endfor %}
</div>
